<?php
require 'config.php'; require_role(['admin','secretary','gso']);$user=current_user();$rows=$conn->query('SELECT a.*,u.full_name,r.reference_no FROM activity_log a LEFT JOIN users u ON a.user_id=u.id LEFT JOIN reservations r ON a.reservation_id=r.id ORDER BY a.created_at DESC LIMIT 200');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Activity Log</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="app"><aside class="sidebar"><a class="side-brand" href="dashboard.php"><span class="brand-icon">⌖</span><span>VEHICLE<br><small>RESERVATION</small></span></a><div class="side-label">WORKSPACE</div><nav><a href="dashboard.php">▦ <span>Dashboard</span></a><a href="reservations.php">▤ <span>Reservations</span></a><?php if(in_array($user['role'],['admin','gso'])):?><a href="vehicles.php">🚙 <span>Vehicles & Drivers</span></a><?php endif;?><a class="active" href="activity.php">◷ <span>Activity Log</span></a></nav><div class="side-bottom"><a href="logout.php">↪ <span>Sign out</span></a></div></aside><main class="main"><header class="topbar"><div class="crumb">Workspace <span>/</span> Activity Log</div><div class="user-chip"><div class="avatar"><?=h(strtoupper(substr($user['name'],0,1)))?></div><div><b><?=h($user['name'])?></b><small><?=h(strtoupper($user['role']))?></small></div></div></header><section class="welcome-row"><div><span class="eyebrow">AUDIT TRAIL</span><h1>Activity log</h1><p>A chronological record of important reservation and fleet actions.</p></div></section><section class="content-card"><div class="table-wrap"><table><thead><tr><th>DATE & TIME</th><th>USER</th><th>ACTION</th><th>REFERENCE</th><th>DETAILS</th></tr></thead><tbody><?php if(!$rows->num_rows):?><tr><td colspan="5" class="empty">No activity recorded yet.</td></tr><?php endif;?><?php while($r=$rows->fetch_assoc()):?><tr><td><?=h(date('M d, Y g:i A',strtotime($r['created_at'])))?></td><td><?=h($r['full_name']??'System')?></td><td><b><?=h($r['action'])?></b></td><td><?=h($r['reference_no']??'—')?></td><td><?=h($r['details'])?></td></tr><?php endwhile;?></tbody></table></div></section><footer>© <?=date('Y')?> LGU Inabanga, Bohol</footer></main></div></body></html>
